/*
 * Fonts downloaded from the Noto Project:
 * https://github.com/notofonts/khmer (also available via Google Fonts:
 * https://fonts.google.com/noto/specimen/Noto+Sans+Khmer)
 *
 * Used as a fallback for Khmer text, which Roboto doesn't support. Embedded as
 * base64 so that ballot rendering doesn't depend on fonts installed on the
 * rendering machine.
 */

import { css } from 'styled-components';

export const NOTO_SANS_KHMER_FONT_DECLARATIONS = css`
  @font-face {
    font-family: 'Noto Sans Khmer';
    font-weight: 400;
    font-style: normal;
    src: url('data:font/truetype;charset=utf-8;base64,')
      format('truetype');
  }

  @font-face {
    font-family: 'Noto Sans Khmer';
    font-weight: 700;
    font-style: normal;
    src: url('data:font/truetype;charset=utf-8;base64,')
      format('truetype');
  }
`;
